3445	    /// Perform a raw bulk-memory-like libcall.
3446	    ///
3447	    /// The main purpose of this helper is to handle situations when fuel and
3448	    /// epochs are enabled to break up the copy into a loop of chunks with
3449	    /// preemption checks between them.
3450	    fn raw_bulk_memory_operation(&mut self, builder: &mut FunctionBuilder<'_>, mut op: BulkOp) {
3451	        // Very scientifically chosen. Or, more seriously, this is just an
3452	        // arbitrary number for now. 100k copies of this size locally takes half
3453	        // a second, so seems like a reasonably large chunk size to not hit perf
3454	        // too much by chunking but also enable time slicing.
3455	        const UNINTERRUPTABLE_CHUNK_SIZE: i64 = 128 << 20;
3456	
3457	        let mut pos = builder.cursor();
3458	        let vmctx = self.vmctx_val(&mut pos);
3459	        let pointer_type = self.pointer_type();
3460	
3461	        // Performs a raw call to the actual libcall, as dictated by the
3462	        // provided `op`. This unconditionally inserts epoch/fuel checks for all
3463	        // calls.
3464	        let raw_call =
3465	            |env: &mut FuncEnvironment<'_>, builder: &mut FunctionBuilder<'_>, op: &_| {
3466	                if env.tunables.epoch_interruption {
3467	                    env.epoch_check(builder);
3468	                }
3469	                match *op {
3470	                    BulkOp::MemoryCopy { dst, src, len } => {
3471	                        if env.tunables.consume_fuel {
3472	                            // Note that fuel is always a 64-bit counter.
3473	                            let fuel_consumed = match env.pointer_type() {
3474	                                ir::types::I32 => builder.ins().uextend(ir::types::I64, len),
3475	                                ir::types::I64 => len,
3476	                                _ => unreachable!(),
3477	                            };
3478	                            env.manual_fuel_check(builder, fuel_consumed);
3479	                        }
3480	                        let memory_copy = env.builtin_functions.memory_copy(&mut builder.func);
3481	                        builder.ins().call(memory_copy, &[vmctx, dst, src, len]);
3482	                    }
3483	                    BulkOp::MemoryFill { dst, val, len } => {
3484	                        if env.tunables.consume_fuel {
3485	                            let fuel_consumed = match env.pointer_type() {
3486	                                ir::types::I32 => builder.ins().uextend(ir::types::I64, len),
3487	                                ir::types::I64 => len,
3488	                                _ => unreachable!(),
3489	                            };
3490	                            env.manual_fuel_check(builder, fuel_consumed);
3491	                        }
3492	                        let memory_fill = env.builtin_functions.memory_fill(&mut builder.func);
3493	                        builder.ins().call(memory_fill, &[vmctx, dst, val, len]);
3494	                    }
3495	                }
3496	            };
3497	
3498	        // If epochs and fuel are disabled, then just call the libcall and
3499	        // return. No need for the loops below.
3500	        if !self.tunables.epoch_interruption && !self.tunables.consume_fuel {
3501	            raw_call(self, builder, &op);
3502	            return;
3503	        }
3504	
3505	        // If fuel is enabled, first take all the pending fuel and flush it to
3506	        // our internal variable. This is necessary to avoid picking up all
3507	        // pending fuel on each turn of the loop below.
3508	        if self.tunables.consume_fuel {
3509	            self.fuel_increment_var(builder);
3510	        }
3511	
3512	        let current_block = builder.current_block().unwrap();
3513	        let chunk_block = builder.create_block();
3514	        let last_chunk_block = builder.create_block();
3515	
3516	        builder.ensure_inserted_block();
3517	        builder.insert_block_after(chunk_block, current_block);
3518	        builder.insert_block_after(last_chunk_block, chunk_block);
3519	
3520	        let chunk = builder
3521	            .ins()
3522	            .iconst(pointer_type, UNINTERRUPTABLE_CHUNK_SIZE);
3523	
3524	        // Helper closure to test if the length in `op` is larger than `chunk`,
3525	        // and if so do a single chunk. Else this goes to the final block with
3526	        // the final operation.
3527	        let has_chunk_branch = |builder: &mut FunctionBuilder<'_>, op: &_| {
3528	            let len = match *op {
3529	                BulkOp::MemoryCopy { len, .. } | BulkOp::MemoryFill { len, .. } => len,
3530	            };
3531	            let has_chunk = builder.ins().icmp(IntCC::UnsignedGreaterThan, len, chunk);
3532	            match *op {
3533	                BulkOp::MemoryCopy { dst, src, len } => {
3534	                    builder.ins().brif(
3535	                        has_chunk,
3536	                        chunk_block,
3537	                        &[dst.into(), src.into(), len.into()],
3538	                        last_chunk_block,
3539	                        &[dst.into(), src.into(), len.into()],
3540	                    );
3541	                }
3542	                BulkOp::MemoryFill { dst, len, .. } => {
3543	                    builder.ins().brif(
3544	                        has_chunk,
3545	                        chunk_block,
3546	                        &[dst.into(), len.into()],
3547	                        last_chunk_block,
3548	                        &[dst.into(), len.into()],
3549	                    );
3550	                }
3551	            }
3552	        };
3553	        has_chunk_branch(builder, &op);
3554	
3555	        let append_block_params = |builder: &mut FunctionBuilder<'_>, block, op: &mut _| match op {
3556	            BulkOp::MemoryCopy { dst, src, len } => {
3557	                *dst = builder.append_block_param(block, pointer_type);
3558	                *src = builder.append_block_param(block, pointer_type);
3559	                *len = builder.append_block_param(block, pointer_type);
3560	            }
3561	            BulkOp::MemoryFill { dst, len, .. } => {
3562	                *dst = builder.append_block_param(block, pointer_type);
3563	                *len = builder.append_block_param(block, pointer_type);
3564	            }
3565	        };
3566	
3567	        // In the block with per-chunk copies, each operation performs `chunk`
3568	        // length of bytes and then decrements the current length by `chunk`.
3569	        // Afterwards a condition tests if we do another chunk or break out for
3570	        // the final chunk.
3571	        builder.switch_to_block(chunk_block);
3572	        append_block_params(builder, chunk_block, &mut op);
3573	        let op_len = match &mut op {
3574	            BulkOp::MemoryCopy { len, .. } | BulkOp::MemoryFill { len, .. } => len,
3575	        };
3576	        let remaining_len = *op_len;
3577	        *op_len = chunk;
3578	        raw_call(self, builder, &op);
3579	        match &mut op {
3580	            BulkOp::MemoryCopy { dst, src, len } => {
3581	                *dst = builder.ins().iadd(*dst, chunk);
3582	                *src = builder.ins().iadd(*src, chunk);
3583	                *len = builder.ins().isub(remaining_len, chunk);
3584	            }
3585	            BulkOp::MemoryFill { len, dst, .. } => {
3586	                *dst = builder.ins().iadd(*dst, chunk);
3587	                *len = builder.ins().isub(remaining_len, chunk);
3588	            }
3589	        };
